  "{0} has lost its last port, but loyal servants have not abandoned the flag. This expedition can keep our cause alive overseas until fortune turns.": "{0} 失去了最后的港口，但忠诚的仆人并没有放弃旗帜。这次远征可以让我们的事业在海外继续存在，直到命运转变。",
