  "{0} merchants have a tally for the Ming trade at Ningbo. The {1} have sent a rival mission. Carry me there before their papers reach the shipping office.": "{0}商人对明朝在宁波的贸易进行了统计。 {1} 派出了一个敌对任务。在他们的文件到达运输办公室之前带我去那里。",
