  "Continue the circuit": "继续送书",
  "CONTROLLED SPICES SURRENDERED {0}": "交出的受控香料 {0}",
  "Cooperation as a weapon. That is a finer observation than any measurement of tooth or paw, and one our moralizing bestiaries would likely misunderstand.": "合作作为武器。这是比任何牙齿或爪子测量更精细的观察，而我们的道德寓言可能会误解这一点。",
  "Costly self-igniting pistols are deadly at close range and useful in a landing party.": "昂贵的自燃手枪在近距离内是致命的，在登陆部队中很有用。",
  "Cotton and tobacco occupy the promoters, but neither feeds a hungry harbor town.": "棉花和烟草占据了推动者的地位，但两者都无法养活饥饿的港口小镇。",
  "COULD NOT END CURRENT VOYAGE": "无法结束当前航程",
  "Council": "理事会",
  "Council {0}": "理事会{0}",
  "Court can have it. I need you fit for the next watch.": "Court can have it.我需要你适应下一块手表。",
  "court dialogue destination": "法庭对话目的地",
  "court dialogue origin": "法庭对话起源",
  "Court notice: {0} is gone. {1} now rules {2}.": "法庭通知：{0} 已消失。 {1} 现在规则 {2}。",
  "COVER": "封面",
  "Cranes swing over the crowded wharf while guild clerks tally barrels, bales, and ships waiting on the tide.": "起重机在拥挤的码头上空摆动，行会职员清点桶、捆包和等待涨潮的船只。",
  "cranes, locks, hoops, and sugar-mill repairs": "起重机、锁、箍和糖厂维修",
  "Create a domestic matchlock industry in Japan.": "创建日本国内火绳产业。",
  "Creation and destruction from one furnace. Mark the fresh flows separately from the cultivated slopes; the island's prosperity and danger share a source.": "创造与毁灭来自同一个熔炉。将新鲜水流与耕作斜坡分开标记；岛上的繁荣和危险有一个共同的根源。",
  "Crew": "船员",
