  "curing cod for the voyage back across the Atlantic": "为横渡大西洋的航程腌制鳕鱼",
  "curing fish and preserving provisions for port laborers": "腌鱼和保存港口工人的食物",
  "Current battery: {0}. Faster locks and longer culverins improve reload, damage, and range. Purse {1} db.": "当前电池电量：{0}。更快的锁和更长的长炮可以改善重装、伤害和射程。钱包{1}DB。",
  "Current gear: {0}. Other nets offered: {1}. Purse {2} db.": "当前装备：{0}。提供的其他网络：{1}。钱包{2}DB。",
  "Current harpoon: {0}. A stronger line and truer shaft improve the odds of holding a surfaced whale. Purse {1} db.": "当前鱼叉：{0}。更强的线和更真实的杆可以提高抓住鲸鱼浮出水面的几率。钱包{1}DB。",
  "CURRENT SHIP WILL BE REPLACED": "当前船舶将被替换",
  "Cusabo food and support have kept the settlement alive, but the Proprietors' own crops have disappointed them.": "库萨博的食物和支持使定居点得以生存，但业主们自己的农作物却令他们失望。",
  "Custom": "定制",
  "Custom: {0} crew / {1} guns.{2}{3}": "自定义：船员 {0} / 火炮 {1}。{2}{3}",
