  "Daoist": "道教",
  "Dawn watch. The sea changes color before it changes its mind.": "Dawn watch.大海在改变主意之前会改变颜色。",
  "Dead men tell no tales, but frightened deckhands tell plenty.": "死人不会讲故事，但受惊的水手会讲很多故事。",
