  "Deliver a passenger safely to their destination.": "将乘客安全送到目的地。",
  "Deliver available ingredients": "提供可用的成分",
  "Deliver five passengers safely in one voyage.": "在一次航程中安全运送五名乘客。",
  "Deliver Testaments {0}/{1}": "交付《新约》 {0}/{1}",
  "Delivered {0} x{1}. {2} still needed.": "已交付 {0} x{1}。仍然需要 {2}。",
  "Delivered the last {0} {1}.": "已交付最后一个 {0} {1}。",
