  "France": "法国",
  "Franciscan friar": "方济会修道士",
  "Franciscan patrons' gift": "方济各会赞助人的礼物",
  "Free Pirate Stuff Icons": "免费海盗的东西图标",
  "French": "法语",
  "French Acadian colony": "法属阿卡迪亚殖民地",
  "French Montreal mission settlement": "法国蒙特利尔宣教区",
  "French New France capital": "法国新法兰西首都",
  "French New France settlement": "法属新法兰西定居点",
  "French settlers and Tamoio allies hold Guanabara Bay. Estacio de Sa needs a Portuguese fort at the harbor mouth to contest it.": "法国定居者和塔莫约盟友控制着瓜纳巴拉湾。 Estacio de Sa需要在海港口建一座葡萄牙堡垒来对抗它。",
  "Fresh snow had gathered in sheltered drifts. The party carried it aboard to melt over the galley fire.": "新雪已经聚集在有遮蔽的雪堆中。一行人把它抬上船，在厨房的火上融化。",
  "Fresh snow lay deep along the ice cap. The party filled sacks and melted it over the galley fire.": "新雪沿着冰盖积得很深。一行人装满了麻袋，并在厨房的火上将其融化。",
  "Fresh snow lay deep behind a pressure ridge. The party filled sacks and melted it over the galley fire.": "新雪深藏在压力脊后面。一行人装满了麻袋，并在厨房的火上将其融化。",
  "Fresh tracks led the party to game enough to replenish the stores.": "新的曲目带领队伍进行了足够的游戏来补充商店。",
  "FRESH WATER REFILLED": "补充淡水",
  "Fresh-cut willow and webbed tracks led the shore party to a beaver lodge hidden in a quiet backwater.": "新剪的柳树和带蹼的小道引导着岸边的人们来到了隐藏在安静死水中的海狸小屋。",
  "Friendly": "友好",
  "From hell's heart I struck at it, and the white whale is gone. Now turn us home to {0}. Let this chase end where my life began.": "我发自内心地击打它，白鲸就消失了。现在让我们回到{0}。让这场追逐在我生命开始的地方结束吧。",
  "from Southeast Asia, and I will pay well for the voyage.{0}": "来自东南亚，我将为这次航程支付丰厚的费用。{0}",
  "Fuji stood apart from every other height, a near-perfect cone carrying snow above fields, roads, and the sea. Its symmetry made the mountain feel composed rather than accidental.": "富士山与其他高度截然不同，它是一个近乎完美的圆锥体，承载着田野、道路和海洋上的积雪。它的对称性使这座山显得沉稳而不是偶然。",
  "Full gun ports and fighting crew": "完整的枪口和战斗人员",
  "Furl your colors beyond the headland. Inside this cove, no captain asks where a cargo came from.": "将你的颜色卷到岬角之外。在这个海湾内，没有船长询问货物来自哪里。",
  "Fusta": "福斯塔",
  "Galleass": "Galleass",
  "Galleon": "Galleon",
  "Galleon on a Beam Reach": "横梁上的帆船",
  "Galleys, coasters, and deep-water merchants crowd the harbor, each carrying news from another shore.": "桨帆船、沿海船和深水商船挤满了港口，每艘船都携带着来自另一岸的消息。",
  "Galmuri11": "加尔穆里11",
  "gates, tools, artillery fittings, and government chests": "大门、工具、火炮配件和政府箱子",
  "General Merchant": "普通商户",
  "Genoa": "热那亚",
  "Genoa may change masters again. This deed will not.": "热那亚可能会再次易主。此行为不会。",
  "Genoese": "热那亚人",
  "Gentlemen searching for treasure will still need to cut wood and plant. Bring": "寻找宝藏的绅士们仍然需要砍伐木材和种植植物。带",
  "Geobukseon (Turtle Ship)": "龟船",
  "Giant Panda": "大熊猫",
  "Ginger Farmer": "姜农",
  "Giraffe": "长颈鹿",
  "Give me the treasure account after breakfast. For now, try not to bury yourself.": "早餐后把宝库给我。现在，尽量不要埋葬自己。",
  "gives {0} the stores it needs to become a permanent city.": "为 {0} 提供成为永久城市所需的商店。",
  "Giza": "吉萨",
  "Goa enriched the Crown. Your missing carrack enriched my ledger.": "果阿使王室富裕起来。你失踪的克拉克船丰富了我的账本。",
  "Goa mission-house gift": "果阿宣教所礼物",
  "God's grace and a fair wind to you. It is good to meet another who trusts the Word above distant decrees.": "上帝的恩典和顺风给你。很高兴遇到另一个相信神的话语胜过遥远法令的人。",
  "God's peace attend you, captain. It is good to meet another subject of the English Church.": "愿上帝保佑你，船长。很高兴认识英国教会的另一个主题。",
  "God's peace to you. A shared confession is welcome company in a foreign harbor.": "愿上帝赐平安给你。在外国港口，共同的忏悔是受欢迎的。",
  "God's peace to you. We may differ on Rome, but a sound ledger needs no confession.": "愿上帝赐平安给你。我们可能对罗马有不同看法，但一个健全的账本无需承认。",
  "Gold, ivory, cloth, and provisions pass between inland traders and ocean-going captains on this waterfront.": "黄金、象牙、布料和粮食在这个海滨地区的内陆商人和远洋船长之间传递。",
  "Golden": "金色",
  "Gone Fishing": "去钓鱼",
  "Good afternoon, captain.": "下午好，队长。",
  "Good credit is cargo that takes no hold space. Yours is improving.": "良好的信用是指不占用舱位的货物。你的情况正在改善。",
  "Good evening, captain.": "晚上好，队长。",
  "Good factor! Your harbor has two quays today, and I have docked at both of them.": "好港口商人！今天你们的港口有两个码头，我都停靠在这两个码头。",
  "Good morning, captain.": "早上好，队长。",
  "Good news: I have come to settle accounts. Better news: the floor has stopped listing to port.": "好消息：我来算账了。更好的消息：地板已停止向港口倾斜。",
  "Good. I was afraid our household might be peaceful.": "很好。我还担心我们的家会太安静。",
  "Goodbye, captain. Whatever seas lie ahead, I will never forget the ship that carried me home.": "再见，队长。无论前方有怎样的大海，我都不会忘记那艘载我回家的船。",
  "Governor": "州长",
  "Governor {0}": "州长{0}",
