  "Great Explorer": "伟大的探险家",
  "Great figures scored into the desert. Who were they meant to see?": "伟大的人物进入了沙漠。他们要见谁？",
  "Great walls curve across the plateau, built from fitted stone without a trace of mortar. Narrow passages lead between towers and enclosures above the grasslands.": "长城蜿蜒地横跨高原，由合适的石头建造而成，没有一丝砂浆。狭窄的通道通向草原上方的塔楼和围墙之间。",
