  "Knights Hospitaller": "医院骑士团",
  "Knotted records pass from the landing to waiting runners as coastal cargo begins its journey inland.": "当沿海货物开始向内陆航行时，打结的记录从着陆点传递到等待的跑步者。",
  "Knows when to press a bargain and when to let a factor save face.": "知道何时讨价还价，何时让港口商人保全面子。",
  "Knows where fish gather and how to bring them aboard.": "知道鱼聚集的地方以及如何将它们带上船。",
  "Kobaya": "小早",
  "Kosciuszko is no lonely spire. It is the highest swell in a broad, windswept country of rounded ridges, pale grass, and winter snow.": "科修斯科并不是孤独的尖塔。这是这片广阔、多风的国家中最高的海浪，这里有圆形的山脊、苍白的草地和冬雪。",
  "Kreeee!": "克里耶！",
  "Krrrk!": "咔嚓！",
  "Krrrk?": "克尔克？",
  "Krrrk.": "咔嚓。",
  "Kyoto must hear what was promised at {0}, and what was conspicuously left unsaid.": "京都必须听到 {0} 所承诺的内容，以及明显未说出的内容。",
  "Kyoto's offices reward a quick change of allegiance. Creditors prefer consistency.": "京都的办公室奖励迅速改变效忠对象。债权人更喜欢一致性。",
  "L ALT": "丙氨酸转氨酶",
