  "L META": "左元",
  "L SHIFT": "左移",
  "Lake sturgeon": "湖鲟",
  "Lake Titicaca": "的的喀喀湖",
  "Lake Titicaca lies beneath snow-covered Andes, yet its water spreads like a sea among the high plains. Reed boats and floating reed islands move upon its deep blue surface.": "的的喀喀湖位于冰雪覆盖的安第斯山脉下方，但湖水却像大海一样在高原上蔓延。芦苇船和漂浮的芦苇岛在其深蓝色的表面上移动。",
  "Lake trout": "湖鳟鱼",
  "Lake Victoria": "维多利亚湖",
  "Lake whitefish": "湖白鱼",
  "Lancaran": "Lancaran",
  "Land belongs to the family stories tied to it. I will cross every sea before I let debt cut those ties.": "土地属于与之相关的家庭故事。在让债务切断这些联系之前，我将穿越每一个海洋。",
  "Land killing blow": "给予致命一击",
  "Land Marines": "陆地海军陆战队",
  "land trade": "土地贸易",
