  "Lateen Barque": "三角帆驳船",
  "Lead Hull Sheathing": "铅壳护套",
  "Lead plates can turn aside a glancing shot or protect the hull during a grounding.": "铅板有时能弹开擦过的炮弹，或在搁浅时保护船体。",
  "League": "联赛",
  "Lean stores, maximum trade room": "精益门店，最大交易空间",
  "Leave": "离开",
