  "LEAVE THE {0}": "离开 {0}",
  "LEFT": "左",
  "left port dialogue": "左端口对话",
  "Let it lie": "让它撒谎",
  "LET IT STAY": "让它留下来",
  "Let the chart be blank and the ocean without end. I know the mark I hunt. Towards that white shape I roll, though all the waves of the world lie between us.": "让图表一片空白，让海洋无边无际。我知道我狩猎的目标。我朝着那个白色的形状滚动，尽管世界上所有的波浪都横亘在我们之间。",
  "Letter of marque": "品牌证书",
  "Letters Between Two Churches": "两个教会之间的信件",
  "Letters Between Two Fires": "两场火灾之间的信件",
  "Lie low in the cove": "躺在海湾的低处",
  "Light, strong canvas keeps a lateen rig drawing closer to the wind.": "轻质、坚固的帆布使三角帆能更接近风。",
  "Lightning strike": "雷击",
  "Lightning struck the ship during a storm.": "暴风雨期间，闪电击中了船。",
  "lineage emissary": "宗族使者",
  "Lineage settlement": "血统结算",
  "Lion": "狮子",
  "Lisbon": "里斯本",
  "Living storehouses in its own cheeks. Note the seeds and season; perhaps its hoarding explains how it survives the northern winter.": "自己的脸颊上有活的仓库。注意种子和季节；也许它的囤积解释了它如何度过北方的冬天。",
  "LOADING SHIPS...": "装载船舶...",
  "Local American traditional": "当地美国传统",
  "Local Cusabo assistance may save the settlement, but it must carry its own provisions. Add": "库萨博当地的援助可能会拯救定居点，但必须有自己的规定。添加",
  "Local outfitters carry ship gear, weapons, and working equipment. Stock changes with a port's fortunes, while specialist workshops keep every grade on hand.": "当地装备商提供船舶装备、武器和工作设备。库存随着港口的命运而变化，而专业车间则备有各种等级的产品。",
  "LocalSaveWriteError": "本地保存写入错误",
  "locks, tools, and fittings for a permanent capital": "永久首都的锁具、工具和配件",
  "London": "伦敦",
  "Long haul": "长途",
  "Longship armament: Viking Bows": "长船武器：维京弓",
  "Longsword": "长剑",
  "Look north, Captain. The lights are sailing across the sky.": "向北看，船长。 The lights are sailing across the sky.",
  "Loose stone gave way beneath a sailor crossing a dry ravine. The fall proved fatal.": "水手穿过干涸的峡谷时，松动的石头被压垮了。事实证明，这次坠落是致命的。",
  "Lord": "主",
  "Lord {0}": "领主{0}",
  "Low Poly Ancient Dhow Ship": "低聚古代单桅帆船",
  "Low Poly Borobudur Ship of Sriwijaya": "三佛齐的低聚婆罗浮屠船",
  "Low Poly Canoe - Stylized Game Asset": "Low Poly Canoe - 风格化游戏资源",
  "Low Poly Cartoon Sailing Ships": "低聚卡通帆船",
  "LowPoly Llama": "低多边形羊驼",
  "Luanda needs grain for a population built around a garrison rather than farms.": "罗安达需要粮食来满足驻军而不是农场周围人口的需求。",
  "Luther's Testaments are forbidden. Fortunately, I have read them. Close the chest, captain; my eyesight has failed.": "路德的《新约》是禁书。幸好我读过。把箱子关上吧，船长；看来我的眼神不太好。",
  "Lutheran": "路德教会",
  "Luxury. On my first berth, the rope complained about me.": "奢华。在我的第一个泊位上，绳子向我抱怨。",
  "Macau silk is in the warehouses; Nagasaki's reason for being is now visible on its quays.": "澳门丝绸在仓库；长崎存在的理由现在可以在它的码头上看到。",
  "Machu Picchu": "马丘比丘",
  "Machu Picchu grips a narrow ridge above the river clouds. Terraces hold the slopes in place, while fitted walls shed the mountain rain without sinking or splitting.": "马丘比丘紧握着河云上方的狭窄山脊。梯田将斜坡固定在适当的位置，而安装好的墙壁可以挡住山上的雨水，而不会下沉或分裂。",
  "Magellan": "麦哲伦",
  "Mahayana Buddhist": "大乘佛教",
  "Mahfuz is gone. The notes signed during his raids are not.": "马哈福兹走了。他在突袭期间签署的便条并非如此。",
  "Mahseer": "马赫西尔",
  "Make 10 discoveries in one voyage.": "在一次航程中有 10 个发现。",
  "make a fortress of our exile.": "为我们的流放者建造一座堡垒。",
  "Make every discovery in a single voyage.": "在一次航行中完成每一个发现。",
  "Make for open water": "前往开放水域",
  "Make your first discovery.": "做出你的第一个发现。",
  "Makes every cask and ration stretch farther.": "让每个木桶和口粮都能延伸得更远。",
  "Malacca lost a warehouse. I acquired excellent security.": "马六甲失去了一个仓库。我获得了极好的安全保障。",
  "MALTA GRANT REPORTED +{0} DB": "马耳他赠款报告 +{0} DB",
  "Malta has passed from Spanish hands. We must return to Rome and seek a new brief.": "马耳他已脱离西班牙人之手。我们必须返回罗马并寻求新的简报。",
  "MANIFEST {0}/{1}": "清单 {0}/{1}",
  "Manila needs a Chinese silk cargo to justify the new trans-Pacific capital.": "马尼拉需要中国丝绸货物来证明新的跨太平洋首都的合理性。",
  "Manually assigned crew, guns, and stores": "手动分配人员、枪支和物资",
