  "Martin Luther refused to recant before Emperor Charles V at the Diet of Worms, and the argument has split every tavern in Germany.": "马丁·路德在沃尔姆斯议会上拒绝在查理五世皇帝面前放弃自己的立场，这场争论引起了德国每家酒馆的分歧。",
