  "Port of Call": "停靠港",
  "Port Royal": "皇家港",
  "Port Royal Becomes a City": "皇家港成为一座城市",
  "Port Royal has survived its first year in the sheltered basin. The Habitation, Mi'kmaq trade, and Champlain's Order of Good Cheer give Acadia a durable beginning.": "皇家港已经在庇护盆地度过了第一年。栖息地、米克马克贸易和尚普兰的欢乐勋章为阿卡迪亚提供了一个持久的开端。",
  "Port Royal needs grain before its second winter.": "皇家港在进入第二个冬天之前需要粮食。",
  "port steward": "港口管家",
  "PORT: {0}": "端口：{0}",
  "port:{0}": "端口：{0}",
  "Porters and brokers move between the road and anchorage, watching each new cargo for an opportunity.": "搬运工和经纪人在道路和锚地之间移动，观察每批新货物，寻找机会。",
  "Porters move between river barges and sea-going hulls while brokers compare cargo lists beneath the customs awnings.": "搬运工在河驳船和远洋船体之间移动，而经纪人则在海关遮阳篷下比较货物清单。",
  "Porters unload coastal canoes as runners leave the market with news of every unfamiliar sail.": "当跑步者带着每一次陌生航行的消息离开市场时，搬运工正在卸下沿海独木舟。",
