  "Portuguese crown spice monopoly": "葡萄牙皇冠香料专卖",
  "Portuguese factors keep a small trading post here, joining Patani to their routes through Malacca and Siam.": "葡萄牙港口商人在这里设有一个小型贸易站，将北大年与马六甲和暹罗的路线连接起来。",
  "Portuguese factory and tribute station": "葡萄牙工厂和贡站",
