  "Portuguese fort and pepper factory": "葡萄牙堡垒和胡椒工厂",
  "Portuguese fortress and factory": "葡萄牙堡垒和工厂",
  "Portuguese masons are raising a fort and factory beside the clove anchorage; their flag already covers their warehouse trade.": "葡萄牙泥瓦匠正在丁香锚地旁边修建一座堡垒和工厂；他们的旗帜已经覆盖了他们的仓库贸易。",
  "Portuguese merchant settlement": "葡萄牙商人定居点",
  "Portuguese merchants keep a privileged quarter around the new harbor, while Japanese officials retain the city.": "葡萄牙商人保留了新港口周围的特权区，而日本官员保留了这座城市。",
