  "Powder, provisions, and silence are all for sale. Cove specie: {0} db.": "火药、粮食和沉默都可以出售。海湾币：{0} DB。",
  "Powerful yew bows reach farther across the water, but demand practiced archers.": "强大的紫杉弓在水面上射程更远，但需要熟练的弓箭手。",
