  "proof the first locally made matchlocks beyond the city walls": "证明城墙外第一批本地制造的火绳枪",
  "PROTECTORATE: {0} / {1}": "保护：{0} / {1}",
  "Providence needs trade cloth to honor its agreements and outfit new arrivals.": "普罗维登斯需要贸易布料来履行其协议并为新来者提供服装。",
  "Providence now offers a refuge for conscience under civil government, founded through negotiation with Narragansett leaders rather than a Massachusetts patent.": "普罗维登斯现在为公民政府提供了良心的避难所，该避难所是通过与纳拉甘西特领导人谈判而不是马萨诸塞州的专利建立的。",
  "Prrrraaaah!": "呸呸呸！",
  "Puncak Jaya is a wall of pale, sheer rock above steaming equatorial forest, with snow and ice hidden in its highest folds. I had never seen cold and jungle pressed so close together.": "Puncak Jaya 是一堵苍白、陡峭的岩石墙，位于热气腾腾的赤道森林之上，最高的褶皱中隐藏着冰雪。我从未见过寒冷和丛林如此紧密地结合在一起。",
  "Purchase {0}": "购买{0}",
  "Purchase {0}-day Portuguese cartaz": "购买 {0} 天葡萄牙卡塔兹",
  "Purchase {0}; {1} doubloon vessel trade-in": "购买{0}； {1} 金币船只以旧换新",
  "Purchase a license, settle the fine, surrender controlled spice cargo, or answer to our guns.": "购买许可证、缴纳罚款、交出受管制的香料货物，或者听从我们的枪声。",
  "Purchase prices -{0}": "购买价格 -{0}",
  "Put down the cross-staff. You are not the pilot.": "放下横杆。你不是飞行员。",
  "Put every barrel on my account. Except the wine. I believe the wine has already put me on its account.": "把每一桶都记在我的账户上。除了酒。我相信这酒已经让我满意了。",
  "Put to sea": "投入大海",
  "Put to sea and fight": "出海战斗",
  "Put your bow {0} of {1} and watch for Captain {2}.": "把你的弓放在 {1} 的 {0} 并注意船长 {2}。",
  "Put your bow {0} of {1} and watch for Captain {2}. That rogue carries one scrap of a map worth twelve men's lives.": "把你的弓放在 {1} 的 {0} 并注意船长 {2}。那个盗贼携带着一张价值十二人生命的地图碎片。",
  "Pyramids in Nubia! How many kingdoms has the Nile carried?": "努比亚的金字塔！尼罗河流淌过多少个王国？",
  "Quaker": "贵格会",
  "quays, warehouses, and houses around the new anchorage": "新锚地周围的码头、仓库和房屋",
  "Quebec needs grain before ice closes the St. Lawrence.": "在圣劳伦斯河冰封之前，魁北克需要粮食。",
  "Quebec now anchors New France at the river narrows, sustained by shipping, fur trade, and alliances with the Innu, Algonquin, and Wendat.": "魁北克现在将新法兰西锚定在河流狭窄处，依靠航运、毛皮贸易以及与因努人、阿尔冈昆人和温达特人的联盟来维持。",
