  "Ragusa pays for peace with every great power. Your family merely added one more payment.": "拉古萨为与每一个大国的和平付出了代价。你的家人只是多了一笔付款。",
  "Ragusan": "拉古桑",
  "Raichur's victory procession was splendid. I noticed your paymaster absent from it.": "雷丘尔的胜利游行非常精彩。我注意到你的出纳员不在场。",
  "Rainier loomed above the inland waters, a massive white volcano cut by rivers of ice. Even at great distance it dwarfed the forested ridges in front of it.": "雷尼尔山在内陆水域上空隐约可见，是一座被冰河切割而成的巨大白色火山。即使距离很远，它也比前面的森林山脊相形见绌。",
  "Raise Our Colors": "提高我们的色彩",
  "Reach {0}": "达到 {0}",
  "Read it, then. A river punishes captains who only watch the banks.": "那就读吧。河流惩罚只守望河岸的船长。",
  "Reads shoals and handles a net with confidence.": "自信地阅读浅滩并处理网络。",
  "REALIZED P/L {0} DB": "已实现利润或亏损 {0} DB",
