  "REC {0}:{1}": "REC {0}：{1}",
  "Receive the answer": "收到答复",
  "Recife has become the reef-sheltered warehouse port of Pernambuco. Sugar comes down from the mills, and Atlantic hulls crowd the channel.": "累西腓已成为伯南布哥州的珊瑚礁仓库港口。糖从工厂运来，大西洋的船体挤满了海峡。",
  "Recife needs a full sugar cargo to prove the new harbor can pay.": "累西腓需要满载的糖货来证明新港口有能力支付费用。",
  "Recite the voyage with the navigators": "与航海家一起朗诵航程",
  "Recommend a stricter register": "建议更严格的注册",
  "Reconstructed ash and yew bows complete the longship's fighting equipment.": "重建的白蜡树和紫杉弓完善了长船的战斗装备。",
  "Recovered all {0} pieces of Captain {1}'s map, found the island, and fought the old crew home.": "取回了船长{1}地图的所有{0}碎片，找到了岛屿，并与老船员战斗回家。",
