  "Remarkable. Leave the penguin in my care and I shall pay you {payment} doubloons. I have fish, ink, and several questions he may decline to answer.": "了不起。把企鹅交给我照顾，我将付给你{付款}达布隆。我有鱼、墨水，还有几个他可能拒绝回答的问题。",
