  "Rhinoceros": "犀牛",
  "Rhodes has fallen, but the Order's vows have not. His Holiness would have you carry": "罗德已经倒下了，但骑士团的誓言却没有。尊者希望你携带",
  "Rhodes has fallen, but the Order's vows have not. His Holiness would have you carry a petition to Charles, King of Spain and Emperor, that Malta be granted as a new seat": "罗德已经倒下了，但骑士团的誓言却没有。教皇陛下希望您向西班牙国王兼皇帝查理提出请愿书，要求授予马耳他作为新席位",
  "Rhodes has fallen, but the Order's vows have not. His Holiness would have you carry a petition to Charles, King of Spain and Emperor, that Malta be granted as a new seat{0}": "罗德已经倒下了，但骑士团的誓言却没有。教皇陛下希望您向西班牙国王兼皇帝查尔斯提交一份请愿书，要求授予马耳他一个新席位{0}",
  "Rhodes has fallen, but the Order's vows have not. His Holiness would have you carry a petition to Charles, King of Spain and Emperor, that Malta be granted as a new seat{0}.": "罗德已经倒下了，但骑士团的誓言却没有。教皇陛下希望您向西班牙国王兼皇帝查尔斯提交一份请愿书，要求授予马耳他一个新席位{0}。",
  "Rhodes is lost behind us. At Birgu we shall raise the eight-pointed cross again, and": "罗德迷失在我们身后。在比尔古，我们将再次举起八角十字架，",
  "Rhodes is lost behind us. At Birgu we shall raise the eight-pointed cross again, and make a fortress of our exile.": "罗德迷失在我们身后。在比尔古，我们将再次举起八角十字架，为我们的流亡者建造一座堡垒。",
  "Rhodes still stands before the Ottoman sea, but courage cannot feed its defenders.": "罗德岛仍然矗立在奥斯曼海前，但勇气无法满足其守卫者的需求。",
  "Rhodes still stands before the Ottoman sea, but courage cannot feed its defenders. Carry {0} and a Papal nuncio to {1}.": "罗德岛仍然矗立在奥斯曼海前，但勇气无法满足其守卫者的需求。将{0}和教皇大使带到{1}。",
  "RIGHT": "右",
  "Ring; your presence will show that the Order yet lives.": "戒指；你的存在将表明教团仍然存在。",
  "ritual envoy": "礼使",
  "RIVAL DELEGATION DEFEATED - RETURN TO NINGBO": "对手代表团落败——返回宁波",
  "River craft reach this far, but arrivals are uncommon enough that the market knows your cargo before the ropes are tied.": "河船可以到达这么远的地方，但抵达的情况并不常见，以至于市场在绳索系好之前就知道了您的货物。",
  "River craft, caravans, and sea-going merchants meet here, filling the customs house with a dozen languages.": "河船、商队和航海商人在这里相遇，海关大楼里充满了十几种语言。",
