  "Salmon": "鲑鱼",
  "Salvador needs grain while officials, soldiers, builders, and clergy continue to arrive.": "萨尔瓦多需要粮食，而官员、士兵、建筑商和神职人员不断抵达。",
  "Salvador now stands as Brazil's fortified capital, with government on the heights and Atlantic commerce below.": "萨尔瓦多现在是巴西的坚固首都，政府在高处，大西洋商业在低处。",
  "Sampan": "舢舨",
  "San Agustin needs grain before storms or war cut off the harbor.": "圣奥古斯丁在风暴或战争切断港口之前需要粮食。",
  "sangat singer": "桑加特歌手",
  "Sangat's gift": "桑加特的礼物",
  "Sanriku whaling grounds": "三陆捕鲸场",
  "Santiago de Leon de Caracas now holds the valley, and the Indian name Caracas has already outlasted the one in the charter.": "圣地亚哥·德·莱昂·德·加拉加斯现在占据了这个山谷，而印度名称“加拉加斯”的寿命已经超过了宪章中的名称。",
  "Sao Paulo de Luanda has become Portugal's fortified Angolan port. Its Atlantic wealth comes from inland war and the slave trade.": "圣保罗-罗安达已成为葡萄牙在安哥拉的坚固港口。它的大西洋财富来自内陆战争和奴隶贸易。",
  "Sao Sebastiao cannot secure Guanabara without more powder.": "如果没有更多的火药，圣塞巴斯蒂昂就无法保卫瓜纳巴拉。",
  "Sao Sebastiao has secured Guanabara Bay for Portugal. Around the old redoubt, Rio de Janeiro is becoming a true port.": "圣塞巴斯蒂昂已为葡萄牙确保了瓜纳巴拉湾。在旧堡垒周围，里约热内卢正在成为一个真正的港口。",
