  "Sea Venture survivors built Deliverance and Patience from Bermuda cedar before reaching Jamestown. Their account now inspires a town at St. George's.": "Sea Venture 的幸存者在到达詹姆斯敦之前用百慕大雪松建造了拯救号和耐心号。他们的故事如今为圣乔治镇的一座小镇带来了灵感。",
