  "Set crew, guns, and stores. Extra hands improve field work and gun loading. Smaller stores dump excess provisions without refund.": "设置人员、枪支和物资。额外的人手可以改善现场工作和枪支装载。较小的商店倾倒多余的食物，不予退款。",
