  "Sharifate of Mecca": "麦加谢里夫特",
  "Shasta rises by itself above the forests, a broad volcanic cone with a smaller shoulder beside it. Snowfields catch the light long after the lower country has gone dark.": "沙斯塔在森林上方独自升起，是一个宽阔的火山锥，旁边有一个较小的肩部。低地地区天黑很久之后，雪原仍能看到阳光。",
  "Shawmut has good water but little ready shelter for a fleet of families. Bring": "肖穆特拥有良好的水源，但几乎没有为一大群家庭准备好的住所。带",
  "Shawmut's spring solves the water crisis that plagued Charlestown. We will establish Boston on this narrow peninsula in the country of the Massachusett.": "肖姆特的泉水解决了困扰查尔斯敦的水危机。我们将在马萨诸塞州这个狭窄的半岛上建立波士顿。",
  "Shimazu": "岛津",
