  "Shinto-Buddhist": "神道佛教",
  "SHIP AID: FOOD +{0} WATER +{1}": "船舶援助：食物 +{0} 水 +{1}",
  "Ship Collector": "船舶收藏家",
  "ship lighting": "船舶照明",
