  "Ship's Surgeon": "船舶外科医生",
  "Ships and mills cannot run on promises. Complete the harbor stores with": "船舶和工厂不能兑现承诺。完成港口商店",
  "Ships, carts, and warehouse crews crowd the waterfront; every arrival changes some merchant's plans.": "船只、手推车和仓库工作人员挤满了海滨。每次到来都会改变一些商人的计划。",
  "Shipshape": "船形",
