  "shipyard measurements": "造船厂测量",
  "Shipyard report: a new {0} is for sale in {1}.": "造船厂报告：一艘新的 {0} 正在 {1} 出售。",
  "SHIPYARD RUMOUR": "造船厂传闻",
  "Shogun": "将军",
  "Shogun {0}": "幕府将军{0}",
  "Shogun Ashikaga Yoshiharu has sealed an order for the western sea lords. Carry it from Kyoto to Yamaguchi before private war answers first.": "将军足利义治向西方海王下达了命令。在私人战争首先出现之前将其从京都运到山口。",
  "shogunal messenger": "幕府使者",
  "Shoni": "绍尼",
