  "Shore Party Kit": "岸上派对套件",
  "Short haul": "短途",
  "Show mercy and release": "开恩并释放",
  "Shrine and Temple Together": "神社和寺庙在一起",
  "shrine keeper": "神社守护者",
  "Shrine-temple donors' gift": "神社寺庙捐献者的礼物",
  "shrine-temple steward": "神社寺庙管事",
  "Sichuan": "四川",
  "Sickness and poor water threaten Winthrop's crowded Charlestown camp. Blackstone points them across the river to Shawmut's spring.": "疾病和缺水威胁着温思罗普拥挤的查尔斯敦营地。布莱克斯通指引他们过河前往肖姆特的泉水。",
  "Sight, height, and speed joined into one method. Your bearings may even let us estimate how far above the ground it hunted.": "视线、高度和速度合二为一。您的方位甚至可以让我们估计它在离地面多远的地方搜寻。",
  "Sigiriya": "锡吉里亚",
  "Sigiriya rises sheer above the forest. A stair once passed between the paws of a colossal lion, climbing toward gardens and a fortress balanced upon the summit.": "锡吉里耶高耸于森林之上。曾经有一段楼梯从一只巨大狮子的爪子之间穿过，爬向花园和山顶上的一座堡垒。",
  "Sikh": "锡克教",
  "Silk, seals, and calendars travel outward; sulfur and island wares return. Ceremony keeps the sea road legible.": "丝绸、印章、日历向外传播；硫磺和岛屿商品回归。仪式使海路清晰可见。",
  "Silkscreen": "丝印",
  "simple houses along the Moshassuck and a common landing": "莫沙萨克河沿岸的简单房屋和公共平台",
  "Since I was a child, I have dreamed of seeing the whole world with my own eyes: every impossible mountain, ancient city, and shore beyond the horizon. {0}": "从小我就梦想着亲眼看到整个世界：每一座不可能的山峰、每一座古城、每一座地平线之外的海岸。 {0}",
  "Sing with the sangat": "与桑加特一起唱歌",
  "Sink or force the surrender of an enemy ship.": "击沉或迫使敌舰投降。",
  "Sit down, captain. I shall separate geography from wine before adding either to the atlas.": "坐下吧，队长。在将地理和葡萄酒添加到地图集之前，我将把它们分开。",
  "Sit with the responsum court": "与响应法庭一起坐在一起",
  "Skilled Chef": "熟练的厨师",
  "Skilled Fisher": "熟练的渔夫",
  "Skilled Negotiator": "熟练的谈判者",
  "SKILLS": "技能",
  "Sloth": "树懒",
  "Slowness may be an adaptation rather than a defect. I shall write that cautiously; scholars are very fond of mistaking unfamiliar success for failure.": "缓慢可能是一种适应而不是一种缺陷。我会谨慎地写下这一点；学者们很喜欢把不熟悉的成功误认为是失败。",
  "Small Cog": "小型柯克船",
  "Small hull, small target. Think grateful thoughts.": "船体小，目标小。思考感恩的想法。",
  "Small Iceberg": "小冰山",
  "Small Junk": "小型福船",
  "Smoke that thunders indeed! The whole river vanishes into mist.": "确实是烟雾缭绕！整条河流消失在雾气之中。",
  "Smolensk changed hands. This deed did not.": "斯摩棱斯克易主。这个行为没有。",
  "Snow above the equatorial plains: precisely the sort of truth a comfortable scholar would dismiss as sailors' nonsense. Your careful account will make disbelief harder.": "赤道平原上空有雪：正是这样的事实，一个安逸的学者会认为是水手的胡言乱语。你仔细的叙述会让你更难以相信。",
  "So": "所以",
  "So did I. The voyage would never have meant half as much without you, and I want every year that follows to be ours.": "我也是。如果没有你，这次航行的意义永远不会减少一半，我希望接下来的每一年都是我们的。",
  "Sō envoy": "宗使",
  "So House": "故居",
  "So many merchants came in today that every warehouse keeper claims a shortage.": "今天进来的商家太多了，每个仓库老板都声称缺货。",
  "So the armor is hide, not shell, and its hearing compensates for its sight. That corrects three illustrated manuscripts on my shelf at once.": "所以盔甲是兽皮，而不是外壳，它的听觉弥补了它的视觉。这同时纠​​正了我书架上的三份插图手稿。",
  "So the river that feeds Egypt gathers its strength beneath another sky. Put every inlet you saw upon the chart; the beginning of a river can explain half a continent.": "因此，滋养埃及的河流在另一个天空下积聚了力量。将您看到的每个入口写在海图上；一条河流的起点可以解释半个大陆。",
  "So the tales are true: Captain {0}'s treasure is aboard.": "所以这些故事是真的：{0}船长的宝藏在船上。",
  "So the tales are true: Captain {0}'s treasure is aboard. Heave to. We will take the hoard and leave your crew their lives.": "所以这些故事是真的：{0}船长的宝藏在船上。举起。我们将拿走这些宝藏，并留下你们船员的生命。",
  "So thirsty... We need fresh water.": "太渴了...我们需要淡水。",
  "Sold {0} for {1} db. P/L {2}.": "已售出 {0}，价格为 {1} DB。盈利或亏损{2}。",
  "Sold {0} x{1} for {2} db. P/L {3}.": "已售出 {0} x{1}，价格为 {2} DB。盈利或亏损{3}。",
  "soldiers campaigning inland from the coast": "士兵从海岸向内陆作战",
  "soldiers facing French guns and Tamoio canoes": "面对法国枪支和塔莫约独木舟的士兵",
  "Something in the porcelain crate rattled. Lash it again before profit becomes crockery.": "瓷箱里有什么东西发出嘎嘎声。在利润变成陶器之前再次鞭打它。",
  "Somewhere beyond this water, the white whale still breathes. So do I.": "Somewhere beyond this water, the white whale still breathes.我也一样。",
  "Songhai": "桑海",
  "Songhai Empire": "桑海帝国",
  "Songs from Kartarpur": "来自卡尔塔普尔的歌曲",
  "Southern Ice": "南方冰",
  "Southern minke whale": "南小须鲸",
  "SPACE": "货舱",
