  "TILT {0} DEG": "倾斜 {0} 度",
  "to {0} before another Christian harbor is lost.": "在另一个基督教港口消失之前到达{0}。",
  "To arms": "到武器",
  "To challenge France Antarctique, the fort must also carry": "为了挑战法国南极队，堡垒还必须携带",
  "to you. Selling {0} is theft. The race will fail and your standing": "给你。出售 {0} 属于盗窃行为。比赛将会失败，你的地位",
  "TOO ATTACHED": "太依恋",
  "TOO DANGEROUS TO GO ASHORE": "上岸太危险",
  "Too many settlers have arrived together for local stores to absorb. Add": "太多的定居者聚集在一起，当地商店无法吸收。添加",
  "tools and ship fittings on an isolated island": "孤岛上的工具和船舶配件",
  "tools, gates, and farming implements": "工具、大门和农具",
