  "tradeImpact": "贸易影响",
  "Transferring command": "传输命令",
  "Transplant Old World ginger into the New World.": "将旧世界生姜移植到新世界。",
  "TRAPPED BEAVER HOLD FULL": "被困海狸保持完整",
  "travel:{0}": "旅行：{0}",
