  "Treat it kindly. It cost enough to have opinions.": "善待它。发表意见的成本已经足够了。",
  "Trois-Rivieres has become a permanent fortified fur post at the Saint-Maurice confluence, linking French shipping to Algonquin and Innu trade routes.": "三河市已成为圣莫里斯交汇处的永久防御毛皮哨所，将法国航运与阿尔冈昆和因努贸易路线连接起来。",
  "Trois-Rivieres needs trade cloth before the spring gathering.": "三河城在春季聚会之前需要贸易布料。",
  "Trust travels slowly between ports, but yours has arrived.": "信任在港口之间缓慢传播，但你的已经抵达。",
  "Trusted": "值得信赖",
  "Try to enter in disguise": "尝试伪装进入",
  "Tsushima lives between two courts. Your debt found recognition in both.": "对马岛住在两个法院之间。你的债务得到了双方的认可。",
  "Tulwar": "图尔瓦",
  "Tuna": "金枪鱼",
  "Turn away": "转身离开",
  "Turn them in": "把它们交出来",
  "turned away from recovering port": "拒绝恢复端口",
  "Turning +{0}": "转动 +{0}",
  "Turns observations and soundings into a cleaner passage.": "将观察和探测变成更清晰的通道。",
  "Turtle Ship": "龟船",
  "Turtle Ship Battle": "龟船大战",
  "Turtle Ship versus Atakebune": "龟船与阿武船",
  "Twelve sails followed you toward home, and twelve are gone. Tell me Captain {0}'s treasure was worth the broadside.": "十二张帆跟着你回家，十二张已经消失了。告诉我船长{0}的宝藏值得一炮。",
  "Twelver Shia": "十二什叶派",
  "Twice caught by the same captain. I shall deny this under oath.": "两次被同一个船长抓到。我将在宣誓下否认这一点。",
  "Twin crowns will make it easy to recognize and hard to confuse. Record which summit appeared higher; even a simple distinction can settle years of argument.": "双冠将使其易于识别且不易混淆。记录哪个山峰显得更高；即使是一个简单的区别也能解决多年的争论。",
  "Two faces of the same mountain, depending on the road taken. Your paired sketches prove why one view is never enough for a true chart.": "同一座山的两个面孔，取决于所走的路。您的配对草图证明了为什么一个视图不足以制作真正的图表。",
  "Two Hearts, One Horizon": "两颗心，一个地平线",
  "Two Temples, One Harbor": "两庙一港",
  "Umi-bune": "海船",
  "UNBOUND": "无界",
  "Under {0}'s seal, I place these articles before the court.": "在{0}的印章下，我将这些文章提交给法庭。",
  "Under Portuguese seal, we request a trading harbor at Nagasaki, not Japanese territory. Omura Sumitada's envoys offer six streets under Japanese law.": "根据葡萄牙的印章，我们要求在长崎建立一个贸易港，而不是日本领土。大村纯忠的使者根据日本法律提供了六条街道。",
  "Under the shogun's seal, I deliver this order and require the council's answer.": "在幕府将军的印章下，我发出此命令并要求议会答复。",
  "Undertake the Hajj together": "一起朝觐",
  "Undo all purchases": "撤消所有购买",
  "Undo all sales": "撤消所有销售",
  "UNION DISSOLVED: {0} / {1}": "工会解散：{0} / {1}",
  "UNION: {0} / {1}": "联合： {0} / {1}",
  "Unknown": "未知",
  "UNKNOWN CHEAT: {0}": "未知作弊：{0}",
  "Unlike half this watch. Set an example for them.": "与这款手表的一半不同。为他们树立榜样。",
  "Unload captured guns {0}/{1}": "卸下缴获的枪支{0}/{1}",
  "Unlock the Viking longship.": "解锁维京长船。",
  "UNLOCKED {0}/{1}": "已解锁 {0}/{1}",
  "Until these briefs return to Rome, do not attack the powers receiving us.": "在这些简报返回罗马之前，不要攻击接待我们的权力。",
  "Until these briefs return to Rome, do not attack the powers receiving us. The law of embassies protects the ship only while we honor it.": "在这些简报返回罗马之前，不要攻击接待我们的权力。只有当我们尊重船只时，大使馆法才会保护船只。",
  "UP": "UP",
  "Urca": "Urca",
  "Urge stricter ship papers": "主张收紧船舶文书",
  "Urrrgh!": "呃呃！",
  "Useful endurance, guns, and cargo": "有用的耐力、枪支和货物",
  "Useless": "无用",
  "Valdivia wants a southern base at Penco Bay. This is Mapuche country; the proposed town is a frontier fort in an active war.": "瓦尔迪维亚希望在彭科湾建立一个南部基地。这是马普切人的国家；拟议的城镇是一场激烈战争中的边境堡垒。",
  "Valid against war enemies": "对战争敌人有效",
  "VASSALAGE: {0} / {1}": "血管：{0} / {1}",
  "Venetian": "威尼斯人",
  "Venetian fondaco": "威尼斯方达科",
  "Venetian merchant quarter": "威尼斯商业区",
  "Venetian merchants lodge and trade through their fondaco under the eye of their consul.": "威尼斯商人在领事的监督下通过他们的方达科住宿和交易。",
  "Venice": "威尼斯",
  "Venice called for one loan after another while the mainland burned. Cambrai ended; our obligations did not.": "当大陆被烧毁时，威尼斯要求一笔又一笔贷款。康布雷结束；我们的义务没有。",
  "Very well. But I am not listing it as an able seaman.": "很好。但我并没有将其列为一名能干的海员。",
  "Very well. He may stay, but somebody keep him out of the fish barrel.": "很好。他可能会留下来，但有人阻止他进入鱼桶。",
  "Very well. Lock the larder, count the spoons, and do not call him an able seaman.": "很好。锁上食品储藏室，数数勺子，不要称他为能干的水手。",
  "Very well. The {0} will remain available in the equipment store if you change your mind.": "很好。如果您改变主意，{0} 仍将在设备商店中提供。",
  "Very well. The commission remains available while {0} is at war. Ask me if you reconsider.": "很好。只要{0}仍在交战，这份委任就继续有效。若你改变主意，来找我。",
  "VESSEL: {0}": "船只：{0}",
  "Veteran Whaler": "资深捕鲸者",
  "Victoria cichlid": "维多利亚慈鲷",
  "Victoria Falls": "维多利亚瀑布",
  "Vienna": "维也纳",
  "Vienna holds against Suleiman's army": "维也纳挡住苏莱曼的大军",
  "Vijayanagara": "毗奢耶那伽罗",
  "Vijayanagara Empire": "毗奢耶那伽罗帝国",
  "Vijayanagaran": "毗奢耶那伽兰",
  "Viking Bows": "维京弓",
  "Viking Longship": "维京长船",
  "Villalar settled the Comuneros' quarrel. It also settled your estate beneath my seal.": "维拉尔平息了市议员之间的争吵。它还将你的财产置于我的封印之下。",
  "Ville-Marie endures on Montreal Island, with Maisonneuve's fort and Jeanne Mance's Hotel-Dieu defining the mission settlement together.": "玛丽城在蒙特利尔岛上屹立不倒，迈松纳夫的堡垒和珍妮·曼斯的主宫酒店共同定义了传教区。",
  "Ville-Marie needs linen for Jeanne Mance's hospital.": "玛丽城需要为珍妮·曼斯的医院提供床单。",
  "Visit 25 different ports in one voyage.": "一次航程访问 25 个不同的港口。",
  "Visit 50 different ports in one voyage.": "一次航程访问 50 个不同的港口。",
  "Visit shipyard": "参观造船厂",
  "Visit the hidden yard": "参观隐藏的庭院",
  "visited {0} colony site": "访问了 {0} 殖民地遗址",
